"""Build the static Paperwork document desk from the source-verified manifest."""
from pathlib import Path
import html,json,hashlib
from datetime import date
from urllib.parse import quote,urlparse
ROOT=Path(__file__).resolve().parents[1]
manifest=ROOT/'data/paperwork-documents.json'
if not manifest.exists():raise SystemExit('The verified Paperwork manifest is required before building.')
data=json.loads(manifest.read_text(encoding='utf-8-sig'));docs=data['documents'];categories=data['categories'];esc=lambda x:html.escape(str(x),quote=True)
if not docs:raise SystemExit('Refusing to build an empty document desk.')
if len({d['id'] for d in docs})!=len(docs):raise ValueError('Duplicate document IDs')
labels={c['id']:c['label'] for c in categories}
destination=(ROOT/'03_Research/IndictmentPaperwork').resolve()
for d in docs:
 path=(ROOT/d['file']).resolve()
 if d['category'] not in labels or not path.is_relative_to(destination) or not path.is_file():raise ValueError('Invalid document path or category: '+d['id'])
 if urlparse(d['sourceUrl']).scheme!='https':raise ValueError('Official source must use HTTPS: '+d['id'])
 content=path.read_bytes()
 if not content.startswith(b'%PDF-') or len(content)!=d['bytes'] or hashlib.sha256(content).hexdigest()!=d['sha256']:raise ValueError('Document integrity check failed: '+d['id'])

def date_label(value):
 if not value:return 'Date Not Listed'
 try:return date.fromisoformat(value).strftime('%B %d, %Y').replace(' 0',' ')
 except ValueError:return value

def row(d):
 size=f"{d['bytes']/1048576:.1f} MB" if d['bytes']>=1048576 else f"{round(d['bytes']/1024)} KB"
 stamp=f'<time datetime="{esc(d["date"])}">{esc(date_label(d["date"]))}</time>' if d.get('date') else '<span>Date Not Listed</span>'
 return f'''<article class="pw-document" data-document-id="{esc(d['id'])}"><div class="pw-document-meta"><span class="pw-category">{esc(labels[d['category']])}</span>{stamp}<span>{d['pages']} Pages / {size}</span></div><div><span class="pw-type">{esc(d['type'])}</span><h3 tabindex="-1">{esc(d['title'])}</h3><p class="pw-summary">{esc(d['summary'])}</p><p class="pw-court">{esc(d['jurisdiction'])} &middot; {esc(d['country'])}</p></div><div class="pw-actions"><a class="pw-view" href="PDF-READER.html?file={quote(d['file'],safe='')}">View Document <span aria-hidden="true">&#8599;</span></a><a href="{esc(d['file'])}" download>Download Original <span aria-hidden="true">&#8595;</span></a><a class="pw-original" href="{esc(d['sourceUrl'])}" target="_blank" rel="noopener" aria-label="Official source: {esc(d['title'])}">Official Source <span aria-hidden="true">&#8599;</span></a></div></article>'''
buttons='<button type="button" data-category-filter="all" aria-pressed="true">All Paperwork <span>'+str(len(docs))+'</span></button>'+''.join(f'<button type="button" data-category-filter="{esc(c["id"])}" aria-pressed="false">{esc(c["label"])} <span>{sum(d["category"]==c["id"] for d in docs)}</span></button>' for c in categories)
locations='<option value="all">All Countries And Courts</option><optgroup label="Countries">'+''.join(f'<option value="country:{esc(x)}">{esc(x)}</option>' for x in sorted({d['country'] for d in docs}))+'</optgroup><optgroup label="Courts And Jurisdictions">'+''.join(f'<option value="court:{esc(x)}">{esc(x)}</option>' for x in sorted({d['jurisdiction'] for d in docs}))+'</optgroup>'
types='<option value="all">All Document Types</option>'+''.join(f'<option value="{esc(x)}">{esc(x)}</option>' for x in sorted({d['type'] for d in docs}))
public=[{key:d.get(key,'') for key in ['id','title','summary','country','jurisdiction','category','type','date']} for d in docs]
index=json.dumps(public,ensure_ascii=True).replace('<','\\u003c')
markup=f'''<!doctype html>
<html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Paperwork | Official Criminal Documents | Carceral Collections</title><meta name="description" content="Read original criminal filings and court documents across corruption, drugs, murder, sex trafficking, and fraud. Search the collection and download the documents."><link rel="canonical" href="https://carceralcollections.org/RESEARCH.html"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link href="https://fonts.googleapis.com/css2?family=Source+Sans+3:wght@400;600;700&display=swap" rel="stylesheet"><link rel="stylesheet" href="paperwork.css?v=20260908"><script src="paperwork.js?v=20260908" defer></script><script src="site-theme.js" defer></script><script src="site-analytics.js" defer></script><script src="community-auth.js" defer></script></head><body><a class="pw-skip" href="#pw-results">Skip To The Documents</a><header class="pw-header"><a class="pw-brand" href="index.html">Cheesborough Carceral Collections</a><nav aria-label="Primary navigation"><a href="index.html">Home</a><a href="LAW-LIBRARY.html">Law Library</a><a href="RESEARCH.html" aria-current="page">Paperwork</a><a href="CONTACT.html">Contact</a></nav></header><main><section class="pw-hero" aria-labelledby="pw-title"><div class="pw-edition"><span>The Document Desk</span><span>Original Filings / Open To Read</span></div><div class="pw-hero-grid"><h1 id="pw-title">Paperwork.</h1><p>Behind the headlines, there&rsquo;s a document. Open the filings, follow the case, and read the words for yourself.</p></div><p class="pw-source-note">Charging documents describe allegations; they are not findings of guilt. This collection preserves the filings as issued.</p></section><div class="pw-main"><div class="pw-controls" data-enhanced hidden><label class="pw-search-label" for="pw-search">Find A Case Or Follow A Subject</label><div class="pw-search"><input id="pw-search" type="search" autocomplete="off" placeholder="Search a name, case, court, or topic"><button type="button" id="pw-clear-search" aria-label="Clear search" hidden>&times;</button></div><div class="pw-categories" role="group" aria-label="Document categories">{buttons}</div><div class="pw-filter-row"><div><label for="pw-location">Country Or Jurisdiction</label><select id="pw-location">{locations}</select></div><div><label for="pw-type">Document Type</label><select id="pw-type">{types}</select></div><div><label for="pw-sort">Arrange The Documents</label><select id="pw-sort"><option value="date">Newest Filing First</option><option value="title">Case Title A To Z</option></select></div></div></div><section id="pw-results" aria-labelledby="pw-results-title"><div class="pw-results-heading"><div><h2 id="pw-results-title">Inside The Case Files</h2><p id="pw-count" class="pw-count" role="status" aria-live="polite">{len(docs)} Documents To Read And Download</p></div><button class="pw-reset" id="pw-reset" type="button" hidden>Reset Filters</button></div><div id="pw-documents">{''.join(row(d) for d in docs)}</div><div class="pw-empty" id="pw-empty" hidden><h3>Try Another Way Into The File.</h3><p>No documents match those filters. Try a shorter search or clear the selections.</p><button type="button" id="pw-empty-reset">Show All Documents</button></div><button class="pw-more" id="pw-more" type="button" hidden>Show More Documents</button></section><aside class="pw-related"><p>Keep Following The Record</p><a href="RIVERS-LOVE.html">The Life Of Rivers Love &#8599;</a><a href="BILL-OF-RIGHTS.html">Bill Of Rights Research &#8599;</a></aside></div></main><footer class="pw-footer"><a href="index.html">Cheesborough Carceral Collections</a><p>UK documents contain public sector information licensed under the <a href="https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/">Open Government Licence v3.0</a>.</p></footer><script type="application/json" id="paperwork-index">{index}</script></body></html>'''
(ROOT/'RESEARCH.html').write_text(markup,encoding='utf-8');print('Built Paperwork with',len(docs),'documents:',{c['id']:sum(d['category']==c['id'] for d in docs) for c in categories})
